css:
/* ---------- v10: phone hero as a film card, words underneath ---------- */
@media(max-width:760px){
  #hero{height:auto;min-height:0;background:#0b0d0c}
  .hz{inset:8px 8px auto 8px;height:52svh;min-height:330px;border-radius:26px;overflow:hidden;transform:translateZ(0)}
  .hz video{opacity:0;transition:opacity .35s}
  .hz video.ok{opacity:1}
  .hz::after{inset:0;height:auto;background:linear-gradient(180deg,rgba(8,10,9,.55) 0%,rgba(8,10,9,0) 28%,rgba(8,10,9,0) 68%,rgba(8,10,9,.42) 100%)}
  .hc{position:relative;bottom:auto;padding:calc(max(52svh,330px) + 34px) 0 76px;text-align:left}
  .hl{display:block}
  .pill{position:absolute;left:calc(var(--gut) + 6px);top:calc(max(52svh,330px) - 36px);background:rgba(14,17,15,.55)}
  .hero-h{font-size:clamp(54px,15.8vw,74px);line-height:.9;margin:0 0 14px}
  .hero-p{margin:0;max-width:35ch;color:rgba(255,255,255,.72)}
  .hero-b{margin-top:22px}
  .hero-n{justify-content:flex-start;margin-top:16px}
}
